head.script:
scwin.screenId = "jldstf08051";

///////// 1. 변수 및 선언 영역 /////////

scwin.grd2 = $c.util.getComponent('grd2');

scwin.grd = $c.util.getComponent('grd');

scwin.grd3 = $c.util.getComponent('grd3');

scwin.grd4 = $c.util.getComponent('grd4');

scwin.vScrenID = "ULDSTF08051.gfm";

scwin.vIsurCd = "";

scwin.vLIST_STAT_CD = "Y";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_get_isurcode();
        $c.util.getComponent("rd_rdo11").setValue("1");
        const vEaryRedmpt = $c.util.getParameter($c.frame.srcUrl, "isEaryRedmpt");
        if (vEaryRedmpt === "Y") {
            $c.util.getComponent('img_Etnlist').setSelectedIndex(3);
            await scwin.newCreateFrame3();
        } else {
            $c.util.getComponent('img_Etnlist').setSelectedIndex(1);
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf08051.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts')) : $c.util.getComponent('dts');

scwin.dts_EtnInst = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_EtnInst')) : $c.util.getComponent('dts_EtnInst');

scwin.dts2 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts2')) : $c.util.getComponent('dts2');

scwin.dts3 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts3')) : $c.util.getComponent('dts3');

scwin.dts4 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts4')) : $c.util.getComponent('dts4');

scwin.fr_SecuGrpId = undefined; try { scwin.fr_SecuGrpId = /* sdd-asis-lifecycle:begin fr_SecuGrpId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */SECUGRP_ID_EN/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf08051' }); }

scwin.fr_MktId = undefined; try { scwin.fr_MktId = /* sdd-asis-lifecycle:begin fr_MktId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.lc.fn_getMktId()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf08051' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf08051.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_Etnlist_onselchanged
 * @author Inswave
 * @date 2026. 09. 29
 * @param nIndex
 * @returns
 * @hidden N
*/
scwin.img_Etnlist_onselchanged = async function (nIndex) {
    try {
        /* sdd-asis-lifecycle:begin img_Etnlist_onselchanged — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (nIndex == 1) {
            $c.util.getComponent("rd_rdo11").setValue("1");
            $c.util.getComponent("rd_rdo12").setValue("2");
            $c.util.getComponent("ipt_txb_ISU_CD").setValue("");
            $c.util.getComponent("ipt_txb_ISU_NM").setValue("");
            $c.util.getComponent('slc_cmb_ISUR_CD').setSelectedIndex(0);
        } else {
            if (nIndex == 2) {
                await scwin.search2();
            } else {
                if (nIndex == 3) {
                    await scwin.search3();
                } else {
                    if (nIndex == 4) {
                        await scwin.search4();
                    }
                }
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf08051.img_Etnlist_onselchanged' }); }
};

