/**
 * @event
 * @name scwin.img_Regist_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.img_Regist_onclick = async function () {
    try {
        /* sdd-asis-lifecycle:begin img_Regist_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.util.getComponent('rd_rdo11').getValue() === "1") {
            if (ipt_txb_ISU_CD.value === "") {
                await $c.win.alert($c.data.getMessage("MSG-0015", ""));
                return true;
            }
        }
        fn_GetPar = scwin.getParNew;
        fn_SetPar = undefined;
        if ($c.util.getComponent('rd_rdo12').getValue() === "1") {
            await scwin.newCreateFrame();
        } else {
            await scwin.newpreCreateFrame();
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf08051.img_Regist_onclick' }); }
};

