        $c.fil.doLogSave(scwin.vScrenID, $c.fil.SCREN_PROCS_TP_CD_07);
        if (scwin.dts.CountRow > 0) {
            scwin.grd.GridToExcel($c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "상장폐지내역", "", "8");
        } else {
            await $c.win.alert($c.lc.NO_EXCEL_DATA);
        }
        /* sdd-asis-lifecycle:end */

