/**
 * @method
 * @name scwin.changeRadioBtn
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx
 * @returns
 * @hidden N
*/
scwin.changeRadioBtn = function (idx) {
    /* sdd-asis-lifecycle:begin fn_changeRadioBtn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (idx === "1") {
        $c.util.getComponent('slc_cmb_ISUR_CD').setSelectedIndex(0);
        $c.util.getComponent("rd_rdo11").setValue("1");
        $c.util.getComponent("rd_rdo12").setValue("2");
    } else {
        if (idx === "2") {
            $c.util.getComponent("ipt_txb_ISU_CD").setValue("");
            $c.util.getComponent("ipt_txb_ISU_NM").setValue("");
            $c.util.getComponent("rd_rdo11").setValue("2");
            $c.util.getComponent("rd_rdo12").setValue("1");
        }
    }
    /* sdd-asis-lifecycle:end */
};


